16	const STAGE_WIDTH = 960;
17	const STAGE_HEIGHT = 540;
18	const LAST_SCREEN = 4;
19	/** Drawn size of the big cropped mascot at stage scale 1; the body is about 63% of it. */
20	const MASCOT_SIZE = 620;
21	
22	const welcomeFaces = ["neutre", "curieux", "heureux", "attentif"] as const;
23	const farewellFaces = ["heureux", "neutre", "fier", "timide"] as const;
24	
25	function fitScale() {
26	  return Math.min(1, window.innerWidth / STAGE_WIDTH, window.innerHeight / STAGE_HEIGHT);
27	}
