1	import { useLayoutEffect, useRef, type CSSProperties } from "react";
2	import { gsap } from "gsap";
3	import { SplitText as GsapSplitText } from "gsap/SplitText";
4	import { prefersReducedMotion } from "../mascot/mascotStore";
5	
6	gsap.registerPlugin(GsapSplitText);
7	
8	/**
9	 * React Bits' Split Text, trimmed to what onboarding uses: a headline whose
10	 * letters rise into place once, on mount. GSAP's SplitText keeps an aria-label
11	 * with the whole string, so screen readers still hear one heading.
12	 */
13	export function SplitText({
14	  text,
15	  className,
16	  style,
17	  delay = 0,
18	}: {
19	  text: string;
20	  className?: string;
21	  style?: CSSProperties;
22	  /** Seconds before the first letter moves. */
23	  delay?: number;
24	}) {
25	  const ref = useRef<HTMLHeadingElement>(null);
26	
27	  // biome-ignore lint/correctness/useExhaustiveDependencies: new words need a fresh split.
28	  useLayoutEffect(() => {
29	    const el = ref.current;
30	    if (!el || prefersReducedMotion()) return;
31	    let split: GsapSplitText | null = null;
32	    let tween: gsap.core.Tween | null = null;
33	    let cancelled = false;
34	
35	    // Splitting measures glyphs, so it waits for the face. Hidden meanwhile,
36	    // or the finished headline would flash before its letters drop out.
37	    const run = () => {
38	      if (cancelled) return;
39	      split = GsapSplitText.create(el, { type: "words,chars" });
40	      el.style.visibility = "";
41	      tween = gsap.from(split.chars, {
42	        opacity: 0,
43	        y: 40,
44	        duration: 1.25,
45	        ease: "power3.out",
46	        stagger: 0.05,
47	        delay,
48	        onComplete: () => split?.revert(),
49	      });
50	    };
51	    if (document.fonts.status === "loaded") run();
52	    else {
53	      el.style.visibility = "hidden";
54	      void document.fonts.ready.then(run);
55	    }
56	
57	    return () => {
58	      cancelled = true;
59	      tween?.kill();
60	      split?.revert();
61	      el.style.visibility = "";
62	    };
63	  }, [text, delay]);
64	
65	  return (
66	    <h1 ref={ref} className={className} style={style}>
67	      {text}
68	    </h1>
69	  );
70	}
